const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();

app.get('/api/milestones/:milestoneId', async (req, res) => {
  if (!req.user || !req.user.workspaceId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Explicitly traverse and enforce workspace boundary via parent relation
  const milestone = await prisma.projectMilestone.findFirst({
    where: {
      id: req.params.milestoneId,
      project: {
        workspaceId: req.user.workspaceId
      }
    }
  });

  if (!milestone) {
    return res.status(404).json({ error: 'Milestone not found or access denied' });
  }

  res.json({ milestone });
});

app.listen(4041);
